-- RemotePhonebook initial schema.
-- All timestamps are timestamptz (UTC). IDs are UUIDs generated by Postgres.

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ---------------------------------------------------------------------------
-- Users
-- ---------------------------------------------------------------------------
CREATE TABLE users (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  full_name              text NOT NULL CHECK (char_length(full_name) BETWEEN 1 AND 120),
  email                  text,                       -- stored lower-cased
  normalized_phone       text,                       -- E.164
  password_hash          text NOT NULL,              -- argon2id
  ussd_pin_hash          text,                       -- argon2id, optional; only usable from a trusted phone
  email_verified_at      timestamptz,
  phone_verified_at      timestamptz,
  account_status         text NOT NULL DEFAULT 'pending_verification'
                         CHECK (account_status IN ('pending_verification', 'active', 'suspended', 'demo')),
  ussd_enabled           boolean NOT NULL DEFAULT true,
  deletion_policy        text NOT NULL DEFAULT 'mirror' CHECK (deletion_policy IN ('mirror', 'keep')),
  contacts_consent_at    timestamptz,                -- consent to upload contacts to the cloud
  failed_login_count     integer NOT NULL DEFAULT 0,
  locked_until           timestamptz,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT users_identifier_present CHECK (email IS NOT NULL OR normalized_phone IS NOT NULL)
);
CREATE UNIQUE INDEX users_email_key ON users (email) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX users_phone_key ON users (normalized_phone) WHERE normalized_phone IS NOT NULL;

-- Extra phone numbers a user links to the account (e.g. a second SIM).
-- A verified, trusted linked phone may use the USSD PIN login.
CREATE TABLE linked_phones (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id           uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  normalized_phone  text NOT NULL,
  label             text,
  verified_at       timestamptz,
  ussd_trusted      boolean NOT NULL DEFAULT true,
  created_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, normalized_phone)
);
CREATE INDEX linked_phones_phone_idx ON linked_phones (normalized_phone) WHERE verified_at IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Devices and API sessions
-- ---------------------------------------------------------------------------
CREATE TABLE devices (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id            uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device_identifier  text NOT NULL CHECK (char_length(device_identifier) BETWEEN 8 AND 128),
  platform           text NOT NULL CHECK (platform IN ('ios', 'android', 'web', 'other')),
  name               text,
  last_seen_at       timestamptz NOT NULL DEFAULT now(),
  created_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, device_identifier)
);

CREATE TABLE auth_sessions (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device_id     uuid REFERENCES devices(id) ON DELETE CASCADE,
  token_hash    text NOT NULL UNIQUE,      -- HMAC-SHA256 of the bearer token; the token itself is never stored
  expires_at    timestamptz NOT NULL,
  revoked_at    timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  last_used_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX auth_sessions_user_idx ON auth_sessions (user_id);

-- One-time codes for email/phone verification, account recovery, phone linking and USSD step-up.
CREATE TABLE verification_codes (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  purpose      text NOT NULL CHECK (purpose IN ('verify_email', 'verify_phone', 'recovery', 'link_phone', 'ussd_login')),
  channel      text NOT NULL CHECK (channel IN ('email', 'sms')),
  destination  text NOT NULL,
  code_hash    text NOT NULL,
  attempts     integer NOT NULL DEFAULT 0,
  expires_at   timestamptz NOT NULL,
  consumed_at  timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX verification_codes_lookup_idx ON verification_codes (user_id, purpose) WHERE consumed_at IS NULL;

-- ---------------------------------------------------------------------------
-- Contacts
-- ---------------------------------------------------------------------------
-- Every change to a contact or its numbers takes a fresh value from this sequence.
-- Clients pull changes with "version > cursor", so the sequence is the sync cursor.
CREATE SEQUENCE contact_version_seq;

CREATE TABLE contacts (
  id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id                  uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device_id                uuid REFERENCES devices(id) ON DELETE SET NULL,
  source_contact_id        text,       -- stable client-side id, namespaced by device ("<device>:<native id>")
  display_name             text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 200),
  normalized_display_name  text NOT NULL,
  dedupe_key               text NOT NULL,   -- normalized name + sorted numbers; identical keys are shown once
  is_demo                  boolean NOT NULL DEFAULT false,
  version                  bigint NOT NULL DEFAULT nextval('contact_version_seq'),
  last_accessed_at         timestamptz,
  created_at               timestamptz NOT NULL DEFAULT now(),
  updated_at               timestamptz NOT NULL DEFAULT now(),
  deleted_at               timestamptz       -- tombstone; row kept until retention purge so deletions sync
);
CREATE UNIQUE INDEX contacts_source_key ON contacts (user_id, source_contact_id) WHERE source_contact_id IS NOT NULL;
CREATE INDEX contacts_user_name_idx ON contacts (user_id, normalized_display_name) WHERE deleted_at IS NULL;
CREATE INDEX contacts_user_version_idx ON contacts (user_id, version);
CREATE INDEX contacts_user_dedupe_idx ON contacts (user_id, dedupe_key) WHERE deleted_at IS NULL;
CREATE INDEX contacts_user_recent_idx ON contacts (user_id, last_accessed_at DESC) WHERE deleted_at IS NULL AND last_accessed_at IS NOT NULL;
CREATE INDEX contacts_name_trgm_idx ON contacts USING gin (normalized_display_name gin_trgm_ops);

CREATE TABLE contact_numbers (
  id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  contact_id               uuid NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  phone_number             text NOT NULL CHECK (char_length(phone_number) BETWEEN 1 AND 40),  -- as entered
  normalized_phone_number  text NOT NULL,     -- E.164 when parseable, otherwise digits only
  label                    text,
  is_primary               boolean NOT NULL DEFAULT false,
  position                 smallint NOT NULL DEFAULT 0,
  created_at               timestamptz NOT NULL DEFAULT now(),
  updated_at               timestamptz NOT NULL DEFAULT now(),
  UNIQUE (contact_id, normalized_phone_number)
);
CREATE INDEX contact_numbers_contact_idx ON contact_numbers (contact_id, position);
CREATE INDEX contact_numbers_trgm_idx ON contact_numbers USING gin (normalized_phone_number gin_trgm_ops);

CREATE TABLE sync_states (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device_id     uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  last_sync_at  timestamptz,             -- last *successful* sync
  sync_cursor   bigint NOT NULL DEFAULT 0,
  sync_status   text NOT NULL DEFAULT 'never' CHECK (sync_status IN ('never', 'in_progress', 'success', 'error')),
  last_error    text,
  last_stats    jsonb,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, device_id)
);

-- ---------------------------------------------------------------------------
-- USSD
-- ---------------------------------------------------------------------------
CREATE TABLE ussd_sessions (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider_session_id    text NOT NULL UNIQUE,
  caller_phone           text NOT NULL,
  service_code           text NOT NULL,
  network_code           text,
  authenticated_user_id  uuid REFERENCES users(id) ON DELETE CASCADE,
  current_menu           text NOT NULL DEFAULT 'welcome',
  session_state          jsonb NOT NULL DEFAULT '{}'::jsonb,   -- never contains passwords, PINs or codes
  -- Africa's Talking sends the cumulative input ("1*me@x.com*<password>"), so the raw text is never
  -- stored. We keep an HMAC of it and its length to find the newest input and to detect retries.
  last_input_digest      text,
  last_input_length      integer NOT NULL DEFAULT 0,
  last_response          text,
  request_seq            integer NOT NULL DEFAULT 0,
  failed_attempts        integer NOT NULL DEFAULT 0,
  ended_at               timestamptz,
  expires_at             timestamptz NOT NULL,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ussd_sessions_expires_idx ON ussd_sessions (expires_at);
CREATE INDEX ussd_sessions_user_idx ON ussd_sessions (authenticated_user_id);

-- ---------------------------------------------------------------------------
-- Security & operations
-- ---------------------------------------------------------------------------
CREATE TABLE audit_events (
  id          bigserial PRIMARY KEY,
  user_id     uuid REFERENCES users(id) ON DELETE SET NULL,
  event_type  text NOT NULL,
  timestamp   timestamptz NOT NULL DEFAULT now(),
  metadata    jsonb NOT NULL DEFAULT '{}'::jsonb      -- never passwords, codes or tokens
);
CREATE INDEX audit_events_user_idx ON audit_events (user_id, timestamp DESC);
CREATE INDEX audit_events_type_idx ON audit_events (event_type, timestamp DESC);

-- Fixed-window rate-limit counters, shared by all API instances.
CREATE TABLE rate_limits (
  bucket_key    text PRIMARY KEY,
  window_start  timestamptz NOT NULL,
  hits          integer NOT NULL
);

-- Outgoing SMS/email (mock mode only writes here; live mode records delivery status).
CREATE TABLE outbound_messages (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid REFERENCES users(id) ON DELETE CASCADE,
  channel      text NOT NULL CHECK (channel IN ('sms', 'email')),
  destination  text NOT NULL,
  body         text NOT NULL,
  provider     text NOT NULL,
  status       text NOT NULL,
  provider_ref text,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX outbound_messages_created_idx ON outbound_messages (created_at);

-- Key/value bookkeeping, e.g. the highest tombstone version purged.
CREATE TABLE system_meta (
  key    text PRIMARY KEY,
  value  text NOT NULL
);
INSERT INTO system_meta (key, value) VALUES ('tombstones_purged_through_version', '0');
